# Let me start writing the implementation
mkdir -p /tmp/lz4impl && cat > /tmp/lz4impl/test_lib.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Forward declarations for lz4 library
typedef void* LZ4F_cctx;
typedef void* LZ4F_dctx;
typedef size_t LZ4F_errorCode_t;

typedef struct {
    uint32_t stateSize;
} LZ4F_cctx_internal;

typedef enum {
    LZ4F_default=0,
    LZ4F_max64KB=4,
    LZ4F_max256KB=5,
    LZ4F_max1MB=6,
    LZ4F_max4MB=7,
} LZ4F_blockSizeID_t;

typedef enum {
    LZ4F_blockLinked=0,
    LZ4F_blockIndependent,
} LZ4F_blockMode_t;

typedef enum {
    LZ4F_noContentChecksum=0,
    LZ4F_contentChecksumEnabled,
} LZ4F_contentChecksum_t;

typedef enum {
    LZ4F_noBlockChecksum=0,
    LZ4F_blockChecksumEnabled,
} LZ4F_blockChecksum_t;

typedef enum {
    LZ4F_frame=0,
    LZ4F_skippableFrame,
} LZ4F_frameType_t;

typedef struct {
    LZ4F_blockSizeID_t     blockSizeID;
    LZ4F_blockMode_t       blockMode;
    LZ4F_contentChecksum_t contentChecksumFlag;
    LZ4F_frameType_t       frameType;
    unsigned long long     contentSize;
    unsigned               dictID;
    LZ4F_blockChecksum_t   blockChecksumFlag;
} LZ4F_frameInfo_t;

typedef struct {
    LZ4F_frameInfo_t frameInfo;
    int              compressionLevel;
    unsigned         autoFlush;
    unsigned         favorDecSpeed;
    unsigned         reserved[3];
} LZ4F_preferences_t;

extern unsigned LZ4F_isError(LZ4F_errorCode_t code);
extern const char* LZ4F_getErrorName(LZ4F_errorCode_t code);
extern LZ4F_errorCode_t LZ4F_createCompressionContext(LZ4F_cctx** cctxPtr, unsigned version);
extern LZ4F_errorCode_t LZ4F_freeCompressionContext(LZ4F_cctx cctx);
extern size_t LZ4F_compressBegin(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const LZ4F_preferences_t* prefsPtr);
extern size_t LZ4F_compressUpdate(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const void* srcBuffer, size_t srcSize, const void* cOptPtr);
extern size_t LZ4F_compressEnd(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const void* cOptPtr);

int main() {
    printf("Testing LZ4 API...\n");

    LZ4F_cctx* ctx = NULL;
    LZ4F_errorCode_t err = LZ4F_createCompressionContext(&ctx, 100);
    if (LZ4F_isError(err)) {
        printf("Error: %s\n", LZ4F_getErrorName(err));
        return 1;
    }
    printf("Context created successfully!\n");

    LZ4F_preferences_t prefs = {
        .frameInfo = {
            .blockSizeID = LZ4F_max64KB,
            .blockMode = LZ4F_blockIndependent,
            .contentChecksumFlag = LZ4F_contentChecksumEnabled,
        },
        .compressionLevel = 0,
    };

    char src[] = "Hello, World! This is a test.";
    char dst[256];

    size_t n = LZ4F_compressBegin(ctx, dst, sizeof(dst), &prefs);
    printf("compressBegin: %zu\n", n);

    n += LZ4F_compressUpdate(ctx, dst+n, sizeof(dst)-n, src, strlen(src), NULL);
    printf("after update: %zu total\n", n);

    n += LZ4F_compressEnd(ctx, dst+n, sizeof(dst)-n, NULL);
    printf("after end: %zu total\n", n);

    LZ4F_freeCompressionContext(ctx);

    printf("Done!\n");
    return 0;
}
EOF

gcc -o /tmp/lz4impl/test_lib /tmp/lz4impl/test_lib.c -L/lib/x86_64-linux-gnu -llz4 2>&1
/tmp/lz4impl/test_lib 2>&1

