#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef void* LZ4F_cctx;
typedef void* LZ4F_dctx;
typedef size_t LZ4F_errorCode_t;
#define LZ4F_VERSION 100

typedef enum {
    LZ4F_default=0,
    LZ4F_max64KB=4,
    LZ4F_max256KB=5,
    LZ4F_max1MB=6,
    LZ4F_max4MB=7,
} LZ4F_blockSizeID_t;

typedef enum {
    LZ4F_blockLinked=0,
    LZ4F_blockIndependent,
} LZ4F_blockMode_t;

typedef enum {
    LZ4F_noContentChecksum=0,
    LZ4F_contentChecksumEnabled,
} LZ4F_contentChecksum_t;

typedef enum {
    LZ4F_noBlockChecksum=0,
    LZ4F_blockChecksumEnabled,
} LZ4F_blockChecksum_t;

typedef enum {
    LZ4F_frame=0,
    LZ4F_skippableFrame,
} LZ4F_frameType_t;

typedef struct {
    LZ4F_blockSizeID_t     blockSizeID;
    LZ4F_blockMode_t       blockMode;
    LZ4F_contentChecksum_t contentChecksumFlag;
    LZ4F_frameType_t       frameType;
    unsigned long long     contentSize;
    unsigned               dictID;
    LZ4F_blockChecksum_t   blockChecksumFlag;
} LZ4F_frameInfo_t;

typedef struct {
    LZ4F_frameInfo_t frameInfo;
    int              compressionLevel;
    unsigned         autoFlush;
    unsigned         favorDecSpeed;
    unsigned         reserved[3];
} LZ4F_preferences_t;

extern unsigned LZ4F_isError(LZ4F_errorCode_t code);
extern const char* LZ4F_getErrorName(LZ4F_errorCode_t code);
extern LZ4F_errorCode_t LZ4F_createCompressionContext(LZ4F_cctx** cctxPtr, unsigned version);
extern LZ4F_errorCode_t LZ4F_freeCompressionContext(LZ4F_cctx cctx);
extern size_t LZ4F_compressBegin(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const LZ4F_preferences_t* prefsPtr);
extern size_t LZ4F_compressUpdate(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const void* srcBuffer, size_t srcSize, const void* cOptPtr);
extern size_t LZ4F_compressEnd(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const void* cOptPtr);
extern size_t LZ4F_compressBound(size_t srcSize, const LZ4F_preferences_t* prefsPtr);
extern LZ4F_errorCode_t LZ4F_createDecompressionContext(LZ4F_dctx** dctxPtr, unsigned version);
extern LZ4F_errorCode_t LZ4F_freeDecompressionContext(LZ4F_dctx dctx);
extern size_t LZ4F_decompress(LZ4F_dctx dctx, void* dstBuffer, size_t* dstSizePtr, const void* srcBuffer, size_t* srcSizePtr, const void* dOptPtr);
