    printf("LZ4F version: %u\n", LZ4F_getVersion());

    LZ4F_cctx* ctx = NULL;
    LZ4F_errorCode_t err = LZ4F_createCompressionContext(&ctx, LZ4F_VERSION);
    if (LZ4F_isError(err)) {
        printf("Error creating ctx: %s\n", LZ4F_getErrorName(err));
        return 1;
