def format_size(n):
    if n == 0:
        return '-'
    if n < 1024:
        return '%.2f' % n
    elif n < 1024*1024:
        return '%.2fK' % (n / 1024.0)
    elif n < 1024*1024*1024:
        return '%.2fM' % (n / (1024.0*1024.0))
    else:
        return '%.2fG' % (n / (1024.0*1024.0*1024.0))

def format_row(frames, type_str, block, compressed_bytes, uncompressed_bytes, ratio, filename):
    compressed_str = format_size(compressed_bytes) if compressed_bytes else '-'
    uncompressed_str = format_size(uncompressed_bytes) if uncompressed_bytes else '-'
    if ratio is None:
        ratio_str = '         -'  # 9 chars right-aligned
        sep = '   '
    else:
        ratio_str = '%9.2f%%' % ratio
        sep = '  '
    return '%10s%15s%6s%12s%14s%s%s%s' % (
