    DISPLAY(" -r     : operate recursively on directories (sets also -m) \n");
    DISPLAY(" -l     : compress using Legacy format (Linux kernel compression)\n");
    DISPLAY(" -z     : force compression \n");
    DISPLAY(" -D FILE: use FILE as dictionary (compression & decompression)\n");
    DISPLAY(" -B#    : cut file into blocks of size # bytes [32+] \n");
    DISPLAY("                     or predefined block size [4-7] (default: 7) \n");
    DISPLAY(" -BI    : Block Independence (default) \n");
    DISPLAY(" -BD    : Block dependency (improves compression ratio) \n");
    DISPLAY(" -BX    : enable block checksum (default:disabled) \n");
    DISPLAY("--no-frame-crc : disable stream checksum (default:enabled) \n");
    DISPLAY("--content-size : compressed frame includes original size (default:not present)\n");
    DISPLAY("--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n");
    DISPLAY("--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n");
    DISPLAY("--favor-decSpeed: compressed files decompress faster, but are less compressed \n");
    DISPLAY("--fast[=#]: switch to ultra fast compression level (default: 1)\n");
    DISPLAY("--best  : same as -12\n");
    DISPLAY("Benchmark arguments : \n");
    DISPLAY(" -b#    : benchmark file(s), using # compression level (default : 1) \n");
    DISPLAY(" -e#    : test all compression levels from -bX to # (default : 1)\n");
    DISPLAY(" -i#    : minimum evaluation time in seconds (default : 3s) \n");
}

static const char* basename_str(const char* path) {
    const char* base = strrchr(path, '/');
    return base ? base + 1 : path;
}

static int file_exists(const char* path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static long long file_size(const char* path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return (long long)st.st_size;
}

static int is_directory(const char* path) {
    struct stat st;
    if (stat(path, &st) != 0) return 0;
    return S_ISDIR(st.st_mode);
}

/* Format a size value for --list display */
static void format_size_str(char* buf, size_t buflen, unsigned long long size) {
    if (size == 0) {
        snprintf(buf, buflen, "-");
    } else if (size < 1024ULL) {
        snprintf(buf, buflen, "%.2f", (double)size);
    } else if (size < 1024ULL * 1024ULL) {
        snprintf(buf, buflen, "%.2fK", (double)size / 1024.0);
    } else if (size < 1024ULL * 1024ULL * 1024ULL) {
        snprintf(buf, buflen, "%.2fM", (double)size / (1024.0 * 1024.0));
    } else {
        snprintf(buf, buflen, "%.2fG", (double)size / (1024.0 * 1024.0 * 1024.0));
    }
}

/* Load dictionary from file */
static void* load_dict(const char* dictFile, size_t* dictSize) {
    FILE* f = fopen(dictFile, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open dictionary file: %s\n", dictFile);
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    void* dict = malloc(sz);
    if (!dict) { fclose(f); return NULL; }
    fread(dict, 1, sz, f);
    fclose(f);
    *dictSize = sz;
    return dict;
}

