static int compress_file(const char* input_path, const char* output_path, 
                          const Settings* settings, int is_stdin, int is_stdout) {
    FILE* fin = NULL;
    FILE* fout = NULL;
    int result = 0;

    /* Open input */
    if (is_stdin) {
