    long long input_size = 0;
    if (!is_stdin) {
        input_size = file_size(input_path);
    }

    /* Load dictionary if needed */
    void* dict_data = NULL;
    size_t dict_size = 0;
    LZ4F_CDict* cdict = NULL;
    if (settings->dictFile) {
        dict_data = load_dict(settings->dictFile, &dict_size);
        if (!dict_data) { result = 1; goto cleanup; }
        cdict = LZ4F_createCDict(dict_data, dict_size);
    }

    /* Determine block size */
    static const size_t blockSizes[] = {0, 0, 0, 0, 64*1024, 256*1024, 1024*1024, 4*1024*1024};
    if (settings->blockSizeID >= 4 && settings->blockSizeID <= 7) {
        size_t bsz = blockSizes[settings->blockSizeID];
        if (bsz > 0 && g_displayLevel >= 2) {
            DISPLAYLEVEL(2, "using blocks of size %zu KB \n", bsz >> 10);
        }
    }

    if (settings->legacyFormat) {
        /* Legacy format compression */
        size_t bufsize = LEGACY_BLOCK_SIZE;
        char* inbuf = malloc(bufsize);
        char* outbuf = malloc(LZ4_compressBound(bufsize) + 4);

        if (!inbuf || !outbuf) {
            free(inbuf); free(outbuf);
            result = 1; goto cleanup;
        }

        /* Write legacy magic */
        uint32_t magic = LZ4_LEGACY_MAGIC;
        fwrite(&magic, 4, 1, fout);

        unsigned long long total_in = 0, total_out = 4;
        size_t nr;

        while ((nr = fread(inbuf, 1, bufsize, fin)) > 0) {
            int csize = LZ4_compress_default(inbuf, outbuf + 4, (int)nr, LZ4_compressBound((int)nr));
            if (csize <= 0) {
                DISPLAYLEVEL(1, "LZ4_compress_default failed\n");
                free(inbuf); free(outbuf);
                result = 1; goto cleanup;
            }
            uint32_t block_size = (uint32_t)csize;
            memcpy(outbuf, &block_size, 4);
            fwrite(outbuf, 1, 4 + csize, fout);
            total_in += nr;
            total_out += 4 + csize;
        }

        free(inbuf);
        free(outbuf);

        double ratio;
        if (total_in > 0) {
            ratio = (double)total_out / (double)total_in * 100.0;
        } else {
            ratio = 0.0;
        }

        if (g_displayLevel >= 2) {
            unsigned long long mib = total_in >> 20;
            if (ratio == 0.0 || total_in == 0) {
                DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> inf%%   ", mib);
            } else {
                DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> %.2f%%   ", mib, ratio);
            }
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%% \n",
                         total_in, total_out, ratio);
        }
    } else {
        /* Frame format compression */
        LZ4F_preferences_t prefs;
        memset(&prefs, 0, sizeof(prefs));
        prefs.frameInfo.blockSizeID = settings->blockSizeID;
        prefs.frameInfo.blockMode = settings->blockIndependence ? LZ4F_blockIndependent : LZ4F_blockLinked;
        prefs.frameInfo.contentChecksumFlag = settings->contentChecksum ? LZ4F_contentChecksumEnabled : LZ4F_noContentChecksum;
        prefs.frameInfo.blockChecksumFlag = settings->blockChecksum ? LZ4F_blockChecksumEnabled : LZ4F_noBlockChecksum;
        prefs.compressionLevel = settings->compressionLevel;
        prefs.favorDecSpeed = settings->favorDecSpeed;
        if (settings->contentSize && input_size > 0) {
            prefs.frameInfo.contentSize = (unsigned long long)input_size;
        }

