        if (settings->acceleration > 0) {
            prefs.compressionLevel = -(settings->acceleration);
        }

        LZ4F_cctx* cctx = NULL;
        LZ4F_errorCode_t err = LZ4F_createCompressionContext(&cctx, LZ4F_VERSION);
        if (LZ4F_isError(err)) {
            DISPLAYLEVEL(1, "Error creating compression context: %s\n", LZ4F_getErrorName(err));
            result = 1; goto cleanup;
        }

