        size_t bufsize = 65536;
        if (settings->blockSizeID >= 4 && settings->blockSizeID <= 7) {
            bufsize = blockSizes[settings->blockSizeID];
        }
        size_t dstCapacity = LZ4F_compressBound(bufsize, &prefs) + 512;

        char* inbuf = malloc(bufsize);
        char* outbuf = malloc(dstCapacity);
        if (!inbuf || !outbuf) {
            free(inbuf); free(outbuf);
            LZ4F_freeCompressionContext(cctx);
            result = 1; goto cleanup;
