            free(inbuf); free(outbuf);
            LZ4F_freeCompressionContext(cctx);
            result = 1; goto cleanup;
        }
        if (n > 0) fwrite(outbuf, 1, n, fout);

        unsigned long long total_in = 0, total_out = n;
        size_t nr;

        while ((nr = fread(inbuf, 1, bufsize, fin)) > 0) {
            size_t written = LZ4F_compressUpdate(cctx, outbuf, dstCapacity, inbuf, nr, NULL);
            if (LZ4F_isError(written)) {
                DISPLAYLEVEL(1, "LZ4F_compressUpdate error: %s\n", LZ4F_getErrorName(written));
                free(inbuf); free(outbuf);
                LZ4F_freeCompressionContext(cctx);
                result = 1; goto cleanup;
            }
            if (written > 0) fwrite(outbuf, 1, written, fout);
            total_in += nr;
            total_out += written;
        }

        /* Flush and end */
        size_t written = LZ4F_compressEnd(cctx, outbuf, dstCapacity, NULL);
        if (LZ4F_isError(written)) {
            DISPLAYLEVEL(1, "LZ4F_compressEnd error: %s\n", LZ4F_getErrorName(written));
            free(inbuf); free(outbuf);
            LZ4F_freeCompressionContext(cctx);
            result = 1; goto cleanup;
        }
        if (written > 0) fwrite(outbuf, 1, written, fout);
        total_out += written;

        free(inbuf);
        free(outbuf);
        LZ4F_freeCompressionContext(cctx);

        double ratio;
        if (total_in > 0) {
            ratio = (double)total_out / (double)total_in * 100.0;
        } else {
            ratio = (double)total_out > 0 ? 1.0/0.0 : 0.0; /* inf */
        }

        if (g_displayLevel >= 2) {
            unsigned long long mib = total_in >> 20;
            if (total_in == 0) {
                DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> inf%%   ", mib);
            } else {
                DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> %.2f%%   ", mib, ratio);
            }
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%%\n",
                         total_in, total_out, ratio);
        }
    }

cleanup:
    if (fin && !is_stdin) fclose(fin);
    if (fout && !is_stdout) fclose(fout);
    if (cdict) LZ4F_freeCDict(cdict);
    if (dict_data) free(dict_data);
    return result;
}

