/* ========== Decompression ========== */

static int decompress_file(const char* input_path, const char* output_path,
                            const Settings* settings, int is_stdin, int is_stdout, int test_only) {
    FILE* fin = NULL;
    FILE* fout = NULL;
    int result = 0;

    const char* display_name = input_path ? input_path : "stdin";

    /* Open input */
    if (is_stdin) {
        fin = stdin;
    } else {
        fin = fopen(input_path, "rb");
        if (!fin) {
            DISPLAYLEVEL(1, "%s: %s\n", input_path, strerror(errno));
            if (!is_stdin && input_path) {
                /* Try with .lz4 extension stripped for error message */
            }
            return 1;
        }
    }

    /* Open output */
    if (test_only || is_stdout) {
        if (!test_only) fout = stdout;
    } else {
        if (!settings->forceOverwrite && file_exists(output_path)) {
            DISPLAYLEVEL(1, "%s already exists; do you want to overwrite (y/N) ? ", output_path);
            fflush(stderr);
            int c = getchar();
            if (c != 'y' && c != 'Y') {
                DISPLAYLEVEL(1, "    not overwritten  \n");
                if (!is_stdin) fclose(fin);
                return 1;
            }
        }
        fout = fopen(output_path, "wb");
        if (!fout) {
            DISPLAYLEVEL(1, "%s: %s\n", output_path, strerror(errno));
            if (!is_stdin) fclose(fin);
            return 1;
        }
    }

    /* Load dictionary */
    void* dict_data = NULL;
    size_t dict_size = 0;
    if (settings->dictFile) {
        dict_data = load_dict(settings->dictFile, &dict_size);
        if (!dict_data) { result = 1; goto cleanup; }
    }

    /* Read magic number to detect format */
    unsigned char magic_buf[4];
    size_t nr = fread(magic_buf, 1, 4, fin);
    if (nr < 4) {
        if (nr == 0) {
            /* Empty file - output 0 bytes */
            if (g_displayLevel >= 2) {
                DISPLAYLEVEL(2, "\rDecompressed : 0 MiB  ");
                DISPLAYLEVEL(2, "\r%79s\r", "");
                DISPLAYLEVEL(2, "%-31.30s: decoded 0 bytes \n", display_name);
            }
            result = 0;
            goto cleanup;
        }
        DISPLAYLEVEL(1, "%s: Not a valid LZ4 file\n", display_name);
        result = 1;
        goto cleanup;
    }

    uint32_t magic;
    memcpy(&magic, magic_buf, 4);
    /* Convert to little-endian */
    magic = ((uint32_t)magic_buf[0]) | 
            ((uint32_t)magic_buf[1] << 8) | 
            ((uint32_t)magic_buf[2] << 16) | 
            ((uint32_t)magic_buf[3] << 24);

    if (magic == LZ4_LEGACY_MAGIC) {
        /* Legacy format decompression */
        size_t inbufsize = LEGACY_BLOCK_SIZE + 4;
        char* inbuf = malloc(inbufsize);
        char* outbuf = malloc(LEGACY_BLOCK_SIZE);

        if (!inbuf || !outbuf) {
            free(inbuf); free(outbuf);
            result = 1; goto cleanup;
        }

        unsigned long long total_out = 0;

        for (;;) {
            /* Read block size */
            uint32_t block_size_le;
            size_t rr = fread(&block_size_le, 1, 4, fin);
            if (rr == 0) break;  /* End of stream */
            if (rr < 4) {
                DISPLAYLEVEL(1, "Truncated legacy block header\n");
                free(inbuf); free(outbuf);
                result = 1; goto cleanup;
            }

            uint32_t block_size = ((uint32_t)((unsigned char*)&block_size_le)[0]) |
                                  ((uint32_t)((unsigned char*)&block_size_le)[1] << 8) |
                                  ((uint32_t)((unsigned char*)&block_size_le)[2] << 16) |
                                  ((uint32_t)((unsigned char*)&block_size_le)[3] << 24);

            /* Check for EOF marker or embedded magic */
            if (block_size == 0x184C2102 || block_size == 0x184D2204) {
                /* Another frame embedded */
                break;
            }

            if (block_size > (uint32_t)inbufsize) {
                DISPLAYLEVEL(1, "Block too large: %u\n", block_size);
                free(inbuf); free(outbuf);
                result = 1; goto cleanup;
            }

            rr = fread(inbuf, 1, block_size, fin);
            if (rr != block_size) {
                DISPLAYLEVEL(1, "Truncated block data\n");
                free(inbuf); free(outbuf);
                result = 1; goto cleanup;
            }

            int decompressed = LZ4_decompress_safe(inbuf, outbuf, (int)block_size, LEGACY_BLOCK_SIZE);
            if (decompressed < 0) {
                DISPLAYLEVEL(1, "LZ4_decompress_safe failed\n");
                free(inbuf); free(outbuf);
                result = 1; goto cleanup;
            }

            if (!test_only && fout) {
                fwrite(outbuf, 1, decompressed, fout);
            }
            total_out += decompressed;
        }

        free(inbuf);
        free(outbuf);

        if (g_displayLevel >= 2) {
            unsigned long long mib = total_out >> 20;
            DISPLAYLEVEL(2, "\rDecompressed : %llu MiB  ", mib);
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "%-31.30s: decoded %llu bytes \n", display_name, total_out);
        }

    } else if (magic == LZ4_MAGIC) {
        /* LZ4 frame format decompression */
        LZ4F_dctx* dctx = NULL;
        LZ4F_errorCode_t err = LZ4F_createDecompressionContext(&dctx, LZ4F_VERSION);
        if (LZ4F_isError(err)) {
            DISPLAYLEVEL(1, "Error creating decompression context: %s\n", LZ4F_getErrorName(err));
            result = 1; goto cleanup;
        }

        /* We already read 4 bytes (magic), need to process them first */
        /* Read a large chunk including header */
        size_t inbufsize = 65536 * 2;
        size_t outbufsize = 65536 * 4;
        char* inbuf = malloc(inbufsize);
        char* outbuf = malloc(outbufsize);

        if (!inbuf || !outbuf) {
            free(inbuf); free(outbuf);
            LZ4F_freeDecompressionContext(dctx);
            result = 1; goto cleanup;
        }

        /* Put back the magic bytes at start of buffer */
        memcpy(inbuf, magic_buf, 4);

        unsigned long long total_out = 0;
        size_t inbuf_fill = 4;
        int done = 0;

        while (!done) {
            /* Fill up the input buffer */
            size_t to_read = inbufsize - inbuf_fill;
            size_t nr2 = 0;
            if (to_read > 0) {
                nr2 = fread(inbuf + inbuf_fill, 1, to_read, fin);
            }
            inbuf_fill += nr2;

            if (inbuf_fill == 0) break;

            /* Decompress */
            const char* src = inbuf;
            size_t remaining = inbuf_fill;

            while (remaining > 0) {
                size_t dst_size = outbufsize;
                size_t src_size = remaining;

                size_t ret;
                if (dict_data) {
                    ret = LZ4F_decompress_usingDict(dctx, outbuf, &dst_size, src, &src_size,
                                                    dict_data, dict_size, NULL);
                } else {
                    ret = LZ4F_decompress(dctx, outbuf, &dst_size, src, &src_size, NULL);
                }

                if (LZ4F_isError(ret)) {
                    DISPLAYLEVEL(1, "%s: %s\n", display_name, LZ4F_getErrorName(ret));
                    free(inbuf); free(outbuf);
                    LZ4F_freeDecompressionContext(dctx);
                    result = 1; goto cleanup;
                }

                if (!test_only && fout && dst_size > 0) {
                    fwrite(outbuf, 1, dst_size, fout);
                }
                total_out += dst_size;

                src += src_size;
                remaining -= src_size;

                if (ret == 0) {
                    done = 1;
                    break;
                }

                if (src_size == 0 && dst_size == 0) break;
            }

            inbuf_fill = 0;
            if (nr2 == 0 && to_read > 0) done = 1;
        }

        free(inbuf);
        free(outbuf);
        LZ4F_freeDecompressionContext(dctx);

        if (g_displayLevel >= 2) {
            unsigned long long mib = total_out >> 20;
            DISPLAYLEVEL(2, "\rDecompressed : %llu MiB  ", mib);
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "%-31.30s: decoded %llu bytes \n", display_name, total_out);
        }

    } else {
        /* Check if it's a skippable frame or invalid */
        if ((magic & 0xFFFFFFF0U) == LZ4_SKIPPABLE_MAGIC_BASE) {
            /* Skippable frame */
            DISPLAYLEVEL(2, "skippable frame\n");
        } else {
            DISPLAYLEVEL(1, "%s: Not a valid LZ4 file\n", display_name);
            result = 1;
        }
        goto cleanup;
    }

cleanup:
    if (fin && !is_stdin) fclose(fin);
    if (fout && !is_stdout && !test_only && fout != NULL) fclose(fout);
    else if (fout && !test_only && !is_stdout) fclose(fout);
    if (dict_data) free(dict_data);
    return result;
}

