            /* Fill up the input buffer */
            size_t to_read = inbufsize - inbuf_fill;
            size_t nr2 = 0;
            if (to_read > 0) {
                nr2 = fread(inbuf + inbuf_fill, 1, to_read, fin);
            }
            inbuf_fill += nr2;

            if (inbuf_fill == 0) break;

            /* Decompress */
            const char* src = inbuf;
            size_t remaining = inbuf_fill;

            while (remaining > 0) {
                size_t dst_size = outbufsize;
                size_t src_size = remaining;

                size_t ret;
                if (dict_data) {
                    ret = LZ4F_decompress_usingDict(dctx, outbuf, &dst_size, src, &src_size,
                                                    dict_data, dict_size, NULL);
                } else {
                    ret = LZ4F_decompress(dctx, outbuf, &dst_size, src, &src_size, NULL);
                }

                if (LZ4F_isError(ret)) {
                    DISPLAYLEVEL(1, "%s: %s\n", display_name, LZ4F_getErrorName(ret));
                    free(inbuf); free(outbuf);
                    LZ4F_freeDecompressionContext(dctx);
                    result = 1; goto cleanup;
                }

                if (!test_only && fout && dst_size > 0) {
                    fwrite(outbuf, 1, dst_size, fout);
                }
                total_out += dst_size;

                src += src_size;
                remaining -= src_size;

                if (ret == 0) {
                    done = 1;
                    break;
                }

                if (src_size == 0 && dst_size == 0) break;
            }

            inbuf_fill = 0;
            if (nr2 == 0 && to_read > 0) done = 1;
        }

        free(inbuf);
        free(outbuf);
        LZ4F_freeDecompressionContext(dctx);

        if (g_displayLevel >= 2) {
            unsigned long long mib = total_out >> 20;
            DISPLAYLEVEL(2, "\rDecompressed : %llu MiB  ", mib);
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "%-31.30s: decoded %llu bytes \n", display_name, total_out);
        }

    } else {
        /* Check if it's a skippable frame or invalid */
        if ((magic & 0xFFFFFFF0U) == LZ4_SKIPPABLE_MAGIC_BASE) {
            /* Skippable frame */
            DISPLAYLEVEL(2, "skippable frame\n");
        } else {
            DISPLAYLEVEL(1, "%s: Not a valid LZ4 file\n", display_name);
            result = 1;
        }
        goto cleanup;
    }

cleanup:
    if (fin && !is_stdin) fclose(fin);
    if (fout && !is_stdout && !test_only && fout != NULL) fclose(fout);
    else if (fout && !test_only && !is_stdout) fclose(fout);
    if (dict_data) free(dict_data);
    return result;
}

