    } else {
        printf("%10llu%15s%6s%12s%14s%9.2f%%  %s\n",
               frames, type_str, block_str, comp_str, uncomp_str, ratio, filename);
    }
}

static int list_file(const char* path) {
    FILE* fin = fopen(path, "rb");
    if (!fin) {
        fprintf(stderr, "%s: %s\n", path, strerror(errno));
        return 1;
    }

    unsigned char buf[4096];
    size_t nr = fread(buf, 1, sizeof(buf), fin);

    /* Get total file size */
    long long total_file_size = file_size(path);

    unsigned long long frames = 0;
    unsigned long long total_compressed = total_file_size > 0 ? (unsigned long long)total_file_size : 0;
    unsigned long long total_uncompressed = 0;
    int has_uncompressed = 0;
    const char* type_str = "LZ4Frame";
    char block_str[8] = "?";

    if (nr < 4) {
        fclose(fin);
        return 1;
    }

    uint32_t magic = ((uint32_t)buf[0]) | 
                     ((uint32_t)buf[1] << 8) | 
                     ((uint32_t)buf[2] << 16) | 
                     ((uint32_t)buf[3] << 24);

    if (magic == LZ4_LEGACY_MAGIC) {
        frames = 1;
        type_str = "LegacyFrame";
        snprintf(block_str, sizeof(block_str), "-");
        /* Count uncompressed size */
        /* For legacy format, we'd need to decompress to get size */
    } else if (magic == LZ4_MAGIC) {
        /* Count frames and get info */
        LZ4F_dctx* dctx = NULL;
        LZ4F_createDecompressionContext(&dctx, LZ4F_VERSION);

        LZ4F_frameInfo_t fi;
        size_t consumed = nr;
        size_t ret = LZ4F_getFrameInfo(dctx, &fi, buf, &consumed);

        if (!LZ4F_isError(ret)) {
            frames = 1;

            /* Determine block type string */
            char bmode = fi.blockMode == LZ4F_blockIndependent ? 'I' : 'D';
            int bsize_id = fi.blockSizeID;
            if (bsize_id >= 4 && bsize_id <= 7) {
                snprintf(block_str, sizeof(block_str), "B%dI", bsize_id);
                block_str[2] = bmode;
            } else {
                snprintf(block_str, sizeof(block_str), "B?%c", bmode);
            }

            if (fi.contentSize > 0) {
                total_uncompressed = fi.contentSize;
                has_uncompressed = 1;
            }
        }

        LZ4F_freeDecompressionContext(dctx);
    } else {
        type_str = "Unknown";
        snprintf(block_str, sizeof(block_str), "-");
    }

    fclose(fin);

    double ratio = 0.0;
    int show_ratio = 0;
    if (has_uncompressed && total_uncompressed > 0 && total_compressed > 0) {
        ratio = (double)total_compressed / (double)total_uncompressed * 100.0;
        show_ratio = 1;
    }

    /* Get just the basename for display */
    const char* display_name = basename_str(path);

    /* For trailing space after filename (when has ratio) */
    char filename_display[512];
    if (show_ratio) {
        snprintf(filename_display, sizeof(filename_display), "%s ", display_name);
    } else {
        snprintf(filename_display, sizeof(filename_display), "%s", display_name);
    }

    print_list_row(frames, type_str, block_str, total_compressed, 
                   has_uncompressed ? total_uncompressed : 0,
                   ratio, show_ratio, filename_display);

    return 0;
}

