/* ========== Benchmark Mode ========== */

#define BENCH_ITERATIONS 10

typedef struct {
    unsigned long long total_size;
    double cspeed;   /* MB/s */
    double dspeed;   /* MB/s */
    unsigned long long csize;
    double cratio;
} BenchResult;

static double get_time_sec(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static int benchmark_file(const char* path, int level, int min_time_sec, BenchResult* result) {
    FILE* f = fopen(path, "rb");
    if (!f) return 1;

    long long fsize = file_size(path);
    if (fsize <= 0) { fclose(f); return 1; }

    char* srcbuf = malloc(fsize);
    if (!srcbuf) { fclose(f); return 1; }

    fread(srcbuf, 1, fsize, f);
    fclose(f);

    int dstCapacity = LZ4_compressBound((int)fsize) + 64;
    char* dstbuf = malloc(dstCapacity);
    char* decbuf = malloc(fsize + 64);

    if (!dstbuf || !decbuf) {
        free(srcbuf); free(dstbuf); free(decbuf);
        return 1;
    }

    result->total_size = (unsigned long long)fsize;

    const char* bname = basename_str(path);
    char display_name[21];
    snprintf(display_name, sizeof(display_name), "%-20.20s", bname);

    static const char spinner[] = "|/-=\\|-=";
    int spin_idx = 0;

    /* Compression benchmark */
    double best_ctime = 1e10;
    int csize = 0;
    double start_time = get_time_sec();
    double elapsed = 0.0;
    int iterations = 0;

    while (elapsed < (double)min_time_sec) {
        double iter_start = get_time_sec();

        if (level >= 10) {
            /* HC compression */
            csize = LZ4_compressBound((int)fsize);
            /* Use LZ4_compress_HC */
            extern int LZ4_compress_HC(const char* src, char* dst, int srcSize, int dstCapacity, int compressionLevel);
            csize = LZ4_compress_HC(srcbuf, dstbuf, (int)fsize, dstCapacity, level);
        } else if (level <= 0) {
            csize = LZ4_compress_default(srcbuf, dstbuf, (int)fsize, dstCapacity);
        } else if (level == 1) {
            csize = LZ4_compress_default(srcbuf, dstbuf, (int)fsize, dstCapacity);
        } else {
            csize = LZ4_compress_default(srcbuf, dstbuf, (int)fsize, dstCapacity);
        }

        double iter_time = get_time_sec() - iter_start;
        if (iter_time < best_ctime) best_ctime = iter_time;
        elapsed = get_time_sec() - start_time;
        iterations++;

        double speed = (double)fsize / (1024.0 * 1024.0) / iter_time;

        /* Print spinning progress */
        char spin_char = spinner[spin_idx % 4];
        spin_idx++;

        if (g_displayLevel >= 2) {
            if (csize > 0) {
                double ratio = (double)csize / (double)fsize;
                fprintf(stderr, "\r %c-%s   :   %7llu -> %7d (%7.3f), %5.1f MB/s",
                        spin_char, display_name,
                        (unsigned long long)fsize, csize, ratio, speed);
            } else {
                fprintf(stderr, "\r %c-%s   :   %7llu ->",
                        spin_char, display_name, (unsigned long long)fsize);
            }
            fflush(stderr);
        }
    }

    double cspeed = (double)fsize / (1024.0 * 1024.0) / best_ctime;
    double cratio = csize > 0 ? (double)csize / (double)fsize : 0.0;

    if (g_displayLevel >= 2) {
        fprintf(stderr, "\r =-%-20.20s   :   %7llu -> %7d (%7.3f), %5.1f MB/s",
                bname, (unsigned long long)fsize, csize, cratio, cspeed);
        fflush(stderr);
    }

