/* ========== Compression ========== */
static int do_compress(const char* in_path, const char* out_path,
                       const Settings* s, int is_stdin, int is_stdout) {
    FILE* fin = NULL;
    FILE* fout = NULL;
    int result = 0;
    void* dict_data = NULL; size_t dict_size = 0;
    LZ4F_CDict* cdict = NULL;
    double t_start = 0;
    struct timespec ts;

    if (s->verbose >= 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        t_start = ts.tv_sec + ts.tv_nsec * 1e-9;
    }

    if (is_stdin) fin = stdin;
    else {
        fin = fopen(in_path, "rb");
        if (!fin) { DISPLAYLEVEL(1, "%s: %s \n", in_path, strerror(errno)); return 1; }
    }

    if (is_stdout) fout = stdout;
    else {
        if (!s->forceOverwrite && file_exists(out_path)) {
            if (!ask_overwrite(out_path)) { if (!is_stdin) fclose(fin); return 1; }
        }
        fout = fopen(out_path, "wb");
        if (!fout) {
            DISPLAYLEVEL(1, "%s: %s \n", out_path, strerror(errno));
            if (!is_stdin) fclose(fin); return 1;
        }
    }

    long long input_size = is_stdin ? -1 : file_size(in_path);

    if (s->dictFile) {
        dict_data = load_dict(s->dictFile, &dict_size);
        if (!dict_data) { result = 1; goto cleanup; }
        if (!s->legacyFormat)
            cdict = LZ4F_createCDict(dict_data, dict_size);
    }

    /* Report block size if explicitly set */
    if (s->blockSizeID >= 4 && s->blockSizeID <= 7 && g_displayLevel >= 2) {
        size_t bsz = BLOCKSIZES[s->blockSizeID];
        DISPLAYLEVEL(2, "using blocks of size %zu KB \n", bsz >> 10);
    }

    if (s->legacyFormat) {
        /* Legacy format */
        uint32_t magic_le = LZ4_LEGACY_MAGIC;
        char magic_buf[4] = { magic_le & 0xff, (magic_le>>8)&0xff, (magic_le>>16)&0xff, (magic_le>>24)&0xff };
        fwrite(magic_buf, 4, 1, fout);

        size_t bufsize = LEGACY_BLOCKSIZE;
        char* inbuf = malloc(bufsize);
        int bound = LZ4_compressBound((int)bufsize);
        char* outbuf = malloc(bound + 4);
        if (!inbuf || !outbuf) { free(inbuf); free(outbuf); result = 1; goto cleanup; }

        unsigned long long total_in = 0, total_out = 4;
        size_t nr;
        while ((nr = fread(inbuf, 1, bufsize, fin)) > 0) {
            int csize;
            if (dict_data) {
                /* Not supported well in legacy format, just compress without dict */
                csize = LZ4_compress_default(inbuf, outbuf+4, (int)nr, bound);
            } else {
                csize = LZ4_compress_default(inbuf, outbuf+4, (int)nr, bound);
            }
            if (csize <= 0) { DISPLAYLEVEL(1, "compress error\n"); free(inbuf); free(outbuf); result=1; goto cleanup; }
            char* p = outbuf;
            p[0] = csize & 0xff; p[1] = (csize>>8)&0xff; p[2] = (csize>>16)&0xff; p[3] = (csize>>24)&0xff;
            fwrite(outbuf, 1, 4+csize, fout);
            total_in += nr;
            total_out += 4+csize;
        }
        free(inbuf); free(outbuf);

        if (g_displayLevel >= 2) {
            double ratio = total_in > 0 ? (double)total_out / total_in * 100.0 : 0.0;
            unsigned long long mib = total_in >> 20;
            if (total_in == 0) DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> inf%%   ", mib);
            else DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> %.2f%%   ", mib, ratio);
            DISPLAYLEVEL(2, "\r%79s\r", "");
            /* Legacy format shows slightly different final message */
            DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%% \n", total_in, total_out, (total_in>0 ? (double)total_out/total_in*100.0 : 0.0));
        }
    } else {
        /* Frame format */
        LZ4F_preferences_t prefs;
        memset(&prefs, 0, sizeof(prefs));
        prefs.frameInfo.blockSizeID = s->blockSizeID;
        prefs.frameInfo.blockMode = s->blockIndependence ? LZ4F_blockIndependent : LZ4F_blockLinked;
        prefs.frameInfo.contentChecksumFlag = s->contentChecksum ? LZ4F_contentChecksumEnabled : LZ4F_noContentChecksum;
        prefs.frameInfo.blockChecksumFlag = s->blockChecksum ? LZ4F_blockChecksumEnabled : LZ4F_noBlockChecksum;
        prefs.compressionLevel = s->compressionLevel;
        prefs.favorDecSpeed = s->favorDecSpeed;
        if (s->contentSize && input_size > 0)
            prefs.frameInfo.contentSize = (unsigned long long)input_size;
        if (s->acceleration > 0)
            prefs.compressionLevel = -(s->acceleration);

        LZ4F_cctx* cctx = NULL;
        LZ4F_errorCode_t err = LZ4F_createCompressionContext(&cctx, LZ4F_VERSION);
        if (LZ4F_isError(err)) { DISPLAYLEVEL(1, "LZ4F init error: %s\n", LZ4F_getErrorName(err)); result=1; goto cleanup; }

        size_t bufsize = BLOCKSIZES[s->blockSizeID >= 4 && s->blockSizeID <= 7 ? s->blockSizeID : 7];
        if (bufsize == 0) bufsize = 65536;
        size_t dstCap = LZ4F_compressBound(bufsize, &prefs) + 512;
        char* inbuf = malloc(bufsize);
        char* outbuf = malloc(dstCap);
        if (!inbuf || !outbuf) { free(inbuf); free(outbuf); LZ4F_freeCompressionContext(cctx); result=1; goto cleanup; }

        size_t hdr;
        if (cdict) hdr = LZ4F_compressBegin_usingCDict(cctx, outbuf, dstCap, cdict, &prefs);
        else hdr = LZ4F_compressBegin(cctx, outbuf, dstCap, &prefs);
        if (LZ4F_isError(hdr)) { DISPLAYLEVEL(1, "compressBegin error: %s\n", LZ4F_getErrorName(hdr)); free(inbuf); free(outbuf); LZ4F_freeCompressionContext(cctx); result=1; goto cleanup; }
        if (hdr > 0) fwrite(outbuf, 1, hdr, fout);

        unsigned long long total_in = 0, total_out = hdr;
        size_t nr;
        while ((nr = fread(inbuf, 1, bufsize, fin)) > 0) {
            size_t w = LZ4F_compressUpdate(cctx, outbuf, dstCap, inbuf, nr, NULL);
            if (LZ4F_isError(w)) { DISPLAYLEVEL(1, "compressUpdate error: %s\n", LZ4F_getErrorName(w)); free(inbuf); free(outbuf); LZ4F_freeCompressionContext(cctx); result=1; goto cleanup; }
            if (w > 0) fwrite(outbuf, 1, w, fout);
            total_in += nr; total_out += w;
        }

        size_t end_w = LZ4F_compressEnd(cctx, outbuf, dstCap, NULL);
        if (LZ4F_isError(end_w)) { DISPLAYLEVEL(1, "compressEnd error: %s\n", LZ4F_getErrorName(end_w)); free(inbuf); free(outbuf); LZ4F_freeCompressionContext(cctx); result=1; goto cleanup; }
        if (end_w > 0) fwrite(outbuf, 1, end_w, fout);
        total_out += end_w;

        free(inbuf); free(outbuf);
        LZ4F_freeCompressionContext(cctx);

        if (g_displayLevel >= 2) {
            double ratio = total_in > 0 ? (double)total_out / total_in * 100.0 : 0.0;
            unsigned long long mib = total_in >> 20;
            if (total_in == 0) DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> inf%%   ", mib);
            else DISPLAYLEVEL(2, "\rRead : %llu MiB   ==> %.2f%%   ", mib, ratio);
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%%\n", total_in, total_out, ratio);
        }
    }

    if (s->verbose >= 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double t_end = ts.tv_sec + ts.tv_nsec * 1e-9;
        double elapsed = t_end - t_start;
        double mib_per_s = elapsed > 0 ? (file_size(is_stdin ? NULL : in_path) / (1024.0*1024.0)) / elapsed : 0.0;
        /* CPU load would require /proc/stat, approximate */
        DISPLAYLEVEL(3, "Done in %.2f s ==> %.2f MiB/s  (cpu load : %d%%)\n", elapsed, mib_per_s, 99);
    }

cleanup:
    if (fin && !is_stdin) fclose(fin);
    if (fout && !is_stdout) fclose(fout);
    if (cdict) LZ4F_freeCDict(cdict);
    free(dict_data);
    return result;
}

