static int do_decompress(const char* in_path, const char* out_path,
                         const Settings* s, int is_stdin, int is_stdout,
                         int test_only, int auto_out) {
    FILE* fin = NULL;
    FILE* fout = NULL;
    int result = 0;
    void* dict_data = NULL; size_t dict_size = 0;

    const char* display_name = in_path ? in_path : "stdin";

    if (auto_out && in_path && g_displayLevel >= 1) {
        DISPLAYLEVEL(1, "Decoding file %s \n", out_path ? out_path : "");
    }

    if (is_stdin) fin = stdin;
    else {
        fin = fopen(in_path, "rb");
        if (!fin) {
            DISPLAYLEVEL(1, "%s: %s \n", in_path, strerror(errno));
            return 1;
        }
    }

    if (test_only) {
        fout = NULL;
    } else if (is_stdout) {
        fout = stdout;
    } else {
        if (!s->forceOverwrite && file_exists(out_path)) {
            if (!ask_overwrite(out_path)) { if (!is_stdin) fclose(fin); return 1; }
        }
        fout = fopen(out_path, "wb");
        if (!fout) {
            DISPLAYLEVEL(1, "%s: %s \n", out_path, strerror(errno));
            if (!is_stdin) fclose(fin); return 1;
        }
