            size_t nr = to_read > 0 ? fread(inbuf + fill, 1, to_read, fin) : 0;
            fill += nr;
            if (fill == 0) break;

            const char* src = inbuf;
            size_t rem = fill;
            while (rem > 0) {
                size_t dst_sz = obuf_size;
                size_t src_sz = rem;
                size_t ret;
                if (dict_data)
                    ret = LZ4F_decompress_usingDict(dctx, outbuf, &dst_sz, src, &src_sz, dict_data, dict_size, NULL);
                else
                    ret = LZ4F_decompress(dctx, outbuf, &dst_sz, src, &src_sz, NULL);
                if (LZ4F_isError(ret)) {
                    DISPLAYLEVEL(1, "%s: %s\n", display_name, LZ4F_getErrorName(ret));
                    free(inbuf); free(outbuf); LZ4F_freeDecompressionContext(dctx); result=1; goto cleanup;
                }
                if (fout && dst_sz > 0) fwrite(outbuf, 1, dst_sz, fout);
                total_out += dst_sz;
                src += src_sz; rem -= src_sz;
                if (ret == 0) { done = 1; break; }
                if (src_sz == 0 && dst_sz == 0) break;
            }
            fill = 0;
            if (nr == 0 && to_read > 0) done = 1;
        }

        free(inbuf); free(outbuf);
        LZ4F_freeDecompressionContext(dctx);

        if (!result && g_displayLevel >= 2) {
            unsigned long long mib = total_out >> 20;
            DISPLAYLEVEL(2, "\rDecompressed : %llu MiB  ", mib);
            DISPLAYLEVEL(2, "\r%79s\r", "");
            DISPLAYLEVEL(2, "%-31.30s: decoded %llu bytes \n", display_name, total_out);
        }
    } else if ((magic & 0xFFFFFFF0U) == LZ4_SKIPPABLE_BASE) {
        /* Skippable frame - read and discard */
        uint8_t skip_size_buf[4];
        if (fread(skip_size_buf, 1, 4, fin) == 4) {
            uint32_t skip_size = (uint32_t)skip_size_buf[0] | ((uint32_t)skip_size_buf[1]<<8) |
                                 ((uint32_t)skip_size_buf[2]<<16) | ((uint32_t)skip_size_buf[3]<<24);
            fseek(fin, skip_size, SEEK_CUR);
        }
    } else {
        DISPLAYLEVEL(1, "%s: Not a valid LZ4 file\n", display_name);
        result = 1;
    }

cleanup:
    if (fin && !is_stdin) fclose(fin);
    if (fout && !is_stdout && fout) fclose(fout);
    free(dict_data);
    return result;
}

