    else
        printf("%10llu%15s%6s%12s%14s%9.2f%%  %s\n", frames, type, block, cs, us, ratio, fname);
}

static int do_list(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "%s: %s\n", path, strerror(errno)); return 1; }

    long long fsize = file_size(path);
    unsigned char buf[512];
    size_t nr = fread(buf, 1, sizeof(buf), f);
    fclose(f);

    if (nr < 4) return 1;
    uint32_t magic = (uint32_t)buf[0] | ((uint32_t)buf[1]<<8) | ((uint32_t)buf[2]<<16) | ((uint32_t)buf[3]<<24);

    unsigned long long frames = 1;
    unsigned long long cbytes = fsize > 0 ? (unsigned long long)fsize : 0;
    unsigned long long ubytes = 0;
    double ratio = 0.0;
    int has_ratio = 0;
    const char* type = "LZ4Frame";
    char block[8] = "-";

    if (magic == LZ4_LEGACY_MAGIC) {
        type = "LegacyFrame";
        snprintf(block, sizeof(block), "-");
    } else if (magic == LZ4_MAGIC) {
        LZ4F_dctx* dctx = NULL;
        LZ4F_createDecompressionContext(&dctx, LZ4F_VERSION);
        LZ4F_frameInfo_t fi;
        size_t consumed = nr;
        size_t ret = LZ4F_getFrameInfo(dctx, &fi, buf, &consumed);
        LZ4F_freeDecompressionContext(dctx);

        if (!LZ4F_isError(ret)) {
            char bm = (fi.blockMode == LZ4F_blockIndependent) ? 'I' : 'D';
            int bid = fi.blockSizeID;
            if (bid >= 4 && bid <= 7) {
                block[0] = 'B'; block[1] = '0'+bid; block[2] = bm; block[3] = 0;
            } else {
                snprintf(block, sizeof(block), "B?%c", bm);
            }
            if (fi.contentSize > 0) {
                ubytes = fi.contentSize;
                has_ratio = 1;
                ratio = cbytes > 0 ? (double)cbytes / (double)ubytes * 100.0 : 0.0;
            }
        }
    }

    const char* bname = basename_str(path);
    char fname_buf[256];
    if (has_ratio) snprintf(fname_buf, sizeof(fname_buf), "%s ", bname);
    else snprintf(fname_buf, sizeof(fname_buf), "%s", bname);

    print_list_row(frames, type, block, cbytes, ubytes, ratio, has_ratio, fname_buf);
    return 0;
}

