/* ========== Benchmark ========== */
static double get_time_d(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static int do_benchmark(const char* path, int level, int min_time_sec) {
    FILE* f = fopen(path, "rb");
    if (!f) return 1;
    long long fsize = file_size(path);
    if (fsize <= 0) { fclose(f); return 1; }

    char* src = malloc(fsize);
    if (!src) { fclose(f); return 1; }
    fread(src, 1, fsize, f); fclose(f);

    int bound = LZ4_compressBound((int)fsize) + 64;
    char* dst = malloc(bound);
    char* dec = malloc(fsize + 64);
    if (!dst || !dec) { free(src); free(dst); free(dec); return 1; }

    const char* bname = basename_str(path);

    /* Initial clear */
    fprintf(stderr, "\r%79s\r", "");

    /* Compression phase */
    double best_ct = 1e10;
    int csize = 0;
    double start = get_time_d();

    /* First incomplete line on stderr */
    fprintf(stderr, "\r |-%-18.18s:%10lld ->", bname, (long long)fsize);
    fflush(stderr);

    do {
        double t0 = get_time_d();
        if (level >= 10)
            csize = LZ4_compress_HC(src, dst, (int)fsize, bound, level);
        else
            csize = LZ4_compress_default(src, dst, (int)fsize, bound);
        double t1 = get_time_d();
        double dt = t1 - t0;
        if (dt < best_ct) best_ct = dt;
    } while (get_time_d() - start < (double)min_time_sec);

    double cspeed = fsize / (1024.0*1024.0) / best_ct;
    double cratio = csize > 0 ? (double)csize / (double)fsize : 0.0;

    /* stdout: compression result with spinner '/' */
    printf("\r /-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s\r",
           bname, (long long)fsize, csize, cratio, cspeed);
    fflush(stdout);

    /* Decompression phase */
    double best_dt = 1e10;
    start = get_time_d();

    /* Incomplete decompression line on stderr */
    fprintf(stderr, "\r =-%-18.18s:%10lld ->", bname, (long long)fsize);
    fflush(stderr);

    do {
        double t0 = get_time_d();
        LZ4_decompress_safe(dst, dec, csize, (int)fsize);
        double t1 = get_time_d();
        double dt = t1 - t0;
        if (dt < best_dt) best_dt = dt;
    } while (get_time_d() - start < (double)min_time_sec);

    double dspeed = fsize / (1024.0*1024.0) / best_dt;

    /* stdout: decompression result with spinner '=' */
    printf("\r =-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s, %5.1f MB/s\r",
           bname, (long long)fsize, csize, cratio, cspeed, dspeed);
    fflush(stdout);

    /* Second compression pass */
    best_ct = 1e10; start = get_time_d();
    do {
        double t0 = get_time_d();
        if (level >= 10) csize = LZ4_compress_HC(src, dst, (int)fsize, bound, level);
        else csize = LZ4_compress_default(src, dst, (int)fsize, bound);
        double t1 = get_time_d(); double dt = t1-t0;
        if (dt < best_ct) best_ct = dt;
    } while (get_time_d() - start < (double)min_time_sec);
    cspeed = fsize / (1024.0*1024.0) / best_ct;
    cratio = csize > 0 ? (double)csize / (double)fsize : 0.0;

    printf("\r \\-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s\r",
