/* ========== Display Help ========== */
static void display_help(void) {
    fprintf(stderr, "*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***\n");
    fprintf(stderr, "Usage : \n");
    fprintf(stderr, "      %s [arg] [input] [output] \n\n", g_progname);
    fprintf(stderr, "input   : a filename \n");
    fprintf(stderr, "          with no FILE, or when FILE is - or stdin, read standard input\n");
    fprintf(stderr, "Arguments : \n");
    fprintf(stderr, " -1     : fast compression (default) \n");
    fprintf(stderr, " -12    : slowest compression level \n");
    fprintf(stderr, " -T#    : use # threads for compression (default:0==auto) \n");
    fprintf(stderr, " -d     : decompression (default for .lz4 extension)\n");
    fprintf(stderr, " -f     : overwrite output without prompting \n");
    fprintf(stderr, " -k     : preserve source files(s)  (default) \n");
    fprintf(stderr, "--rm    : remove source file(s) after successful de/compression \n");
    fprintf(stderr, " -h/-H  : display help/long help and exit \n\n");
    fprintf(stderr, "Advanced arguments :\n");
    fprintf(stderr, " -V     : display Version number and exit \n");
    fprintf(stderr, " -v     : verbose mode \n");
    fprintf(stderr, " -q     : suppress warnings; specify twice to suppress errors too\n");
    fprintf(stderr, " -c     : force write to standard output, even if it is the console\n");
    fprintf(stderr, " -t     : test compressed file integrity\n");
    fprintf(stderr, " -m     : multiple input files (implies automatic output filenames)\n");
    fprintf(stderr, " -r     : operate recursively on directories (sets also -m) \n");
    fprintf(stderr, " -l     : compress using Legacy format (Linux kernel compression)\n");
    fprintf(stderr, " -z     : force compression \n");
    fprintf(stderr, " -D FILE: use FILE as dictionary (compression & decompression)\n");
    fprintf(stderr, " -B#    : cut file into blocks of size # bytes [32+] \n");
    fprintf(stderr, "                     or predefined block size [4-7] (default: 7) \n");
    fprintf(stderr, " -BI    : Block Independence (default) \n");
    fprintf(stderr, " -BD    : Block dependency (improves compression ratio) \n");
    fprintf(stderr, " -BX    : enable block checksum (default:disabled) \n");
    fprintf(stderr, "--no-frame-crc : disable stream checksum (default:enabled) \n");
    fprintf(stderr, "--content-size : compressed frame includes original size (default:not present)\n");
    fprintf(stderr, "--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n");
    fprintf(stderr, "--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n");
    fprintf(stderr, "--favor-decSpeed: compressed files decompress faster, but are less compressed \n");
    fprintf(stderr, "--fast[=#]: switch to ultra fast compression level (default: 1)\n");
    fprintf(stderr, "--best  : same as -12\n");
    fprintf(stderr, "Benchmark arguments : \n");
    fprintf(stderr, " -b#    : benchmark file(s), using # compression level (default : 1) \n");
    fprintf(stderr, " -e#    : test all compression levels from -bX to # (default : 1)\n");
    fprintf(stderr, " -i#    : minimum evaluation time in seconds (default : 3s) \n");
}

/* ========== Recursive directory processing ========== */
static int process_dir_recursive(const char* dir_path, const Settings* s);
static int process_single_file(const char* in_path, const Settings* s);

static int process_dir_recursive(const char* dir_path, const Settings* s) {
    DIR* d = opendir(dir_path);
    if (!d) { DISPLAYLEVEL(1, "%s: %s\n", dir_path, strerror(errno)); return 1; }
    struct dirent* ent;
    int result = 0;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
        char child[4096];
        snprintf(child, sizeof(child), "%s/%s", dir_path, ent->d_name);
        if (is_directory(child)) {
            result |= process_dir_recursive(child, s);
        } else {
            result |= process_single_file(child, s);
        }
    }
    closedir(d);
    return result;
}

static int process_single_file(const char* in_path, const Settings* s) {
    int result = 0;

    if (s->mode == MODE_LIST) {
        return do_list(in_path);
    }

    if (s->mode == MODE_BENCH) {
        int level_start = s->benchLevel > 0 ? s->benchLevel : 1;
        int level_end = s->benchLevelEnd >= level_start ? s->benchLevelEnd : level_start;
        int min_time = s->benchMinTime > 0 ? s->benchMinTime : 3;

        if (level_end > level_start) {
            fprintf(stderr, "Benchmarking levels from %d to %d\n\n", level_start, level_end);
        }

        for (int lvl = level_start; lvl <= level_end; lvl++) {
            result |= do_benchmark(in_path, lvl, min_time);
            printf("\r %d#\n", lvl);
            fflush(stdout);
        }
        return result;
    }

    if (s->mode == MODE_DECOMPRESS || s->mode == MODE_TEST) {
        /* Determine output path */
        char out_path[4096] = "";
        int auto_out = 0;

        if (s->mode == MODE_TEST) {
            /* Test mode: no output */
            result = do_decompress(in_path, NULL, s, 0, 0, 1, 0);
        } else if (s->toStdout) {
            result = do_decompress(in_path, NULL, s, 0, 1, 0, 0);
        } else {
            /* Auto-derive output filename */
            if (has_lz4_suffix(in_path)) {
                strip_lz4_suffix(in_path, out_path, sizeof(out_path));
                auto_out = 1;
            } else {
                snprintf(out_path, sizeof(out_path), "%s", in_path);
                DISPLAYLEVEL(1, "%s has unknown suffix\n", in_path);
                return 1;
            }
            result = do_decompress(in_path, out_path, s, 0, 0, 0, auto_out);
        }
    } else {
        /* Compress */
        char out_path[4096];
        snprintf(out_path, sizeof(out_path), "%s.lz4", in_path);

        if (s->toStdout) {
            result = do_compress(in_path, NULL, s, 0, 1);
        } else {
            result = do_compress(in_path, out_path, s, 0, 0);
        }
    }

    if (result == 0 && s->removeSource) {
        remove(in_path);
    }

    return result;
}

