/* ========== Main ========== */
int main(int argc, char** argv) {
    Settings s;
    memset(&s, 0, sizeof(s));
    s.mode = MODE_COMPRESS;
    s.blockSizeID = LZ4F_max4MB;
    s.blockIndependence = 1;
    s.contentChecksum = 1;
    s.benchLevel = 1;
    s.benchMinTime = 3;

    /* Determine program name for argv[0] behavior */
    const char* prog = basename_str(argv[0]);
    g_progname = prog;

    /* lz4cat / unlz4 behaviors */
    int is_lz4cat = (strcmp(prog, "lz4cat") == 0);
    int is_unlz4 = (strcmp(prog, "unlz4") == 0);

    if (is_lz4cat) {
        s.mode = MODE_DECOMPRESS;
        s.toStdout = 1;
        s.multipleFiles = 1;
        s.forceOverwrite = 1;
    } else if (is_unlz4) {
        s.mode = MODE_DECOMPRESS;
    }

    /* Argument arrays */
    const char* input_files[4096];
    int num_inputs = 0;
    const char* output_file = NULL;
    int mode_set = 0;
    int list_mode = 0;

    /* Parse arguments */
    for (int i = 1; i < argc; i++) {
        const char* arg = argv[i];

        /* Long options */
        if (strcmp(arg, "--compress") == 0 || strcmp(arg, "-z") == 0) {
            s.mode = MODE_COMPRESS; mode_set = 1; continue;
        }
        if (strcmp(arg, "--decompress") == 0 || strcmp(arg, "--uncompress") == 0) {
            s.mode = MODE_DECOMPRESS; mode_set = 1; continue;
        }
        if (strcmp(arg, "--test") == 0) {
            s.mode = MODE_TEST; mode_set = 1; continue;
        }
        if (strcmp(arg, "--rm") == 0) { s.removeSource = 1; continue; }
        if (strcmp(arg, "--keep") == 0) { s.removeSource = 0; continue; }
        if (strcmp(arg, "--force") == 0) { s.forceOverwrite = 1; continue; }
        if (strcmp(arg, "--no-frame-crc") == 0) { s.contentChecksum = 0; continue; }
        if (strcmp(arg, "--content-size") == 0) { s.contentSize = 1; continue; }
        if (strcmp(arg, "--favor-decSpeed") == 0) { s.favorDecSpeed = 1; continue; }
        if (strcmp(arg, "--sparse") == 0) { continue; } /* ignore */
        if (strcmp(arg, "--no-sparse") == 0) { continue; } /* ignore */
        if (strcmp(arg, "--best") == 0) { s.compressionLevel = 12; continue; }
        if (strcmp(arg, "--fast") == 0) { s.acceleration = 1; continue; }
        if (strncmp(arg, "--fast=", 7) == 0) {
            s.acceleration = atoi(arg+7);
            if (s.acceleration <= 0) s.acceleration = 1;
            continue;
        }
        if (strcmp(arg, "--list") == 0) { s.mode = MODE_LIST; list_mode = 1; continue; }
        if (strncmp(arg, "--list", 6) == 0 && arg[6] == ' ') {
            s.mode = MODE_LIST; list_mode = 1; continue;
        }

        /* -D FILE: dictionary */
        if (strcmp(arg, "-D") == 0) {
            if (i+1 < argc) { s.dictFile = argv[++i]; continue; }
            continue;
        }

        /* Short options */
        if (arg[0] == '-' && arg[1] != 0) {
            const char* p = arg + 1;
            while (*p) {
                char c = *p;
                if (c == 'd') { s.mode = MODE_DECOMPRESS; mode_set = 1; }
                else if (c == 'z') { s.mode = MODE_COMPRESS; mode_set = 1; }
                else if (c == 'f') { s.forceOverwrite = 1; }
                else if (c == 'k') { s.removeSource = 0; }
                else if (c == 'c') { s.toStdout = 1; }
                else if (c == 't') { s.mode = MODE_TEST; mode_set = 1; }
                else if (c == 'm') { s.multipleFiles = 1; }
                else if (c == 'r') { s.recursive = 1; s.multipleFiles = 1; }
                else if (c == 'l') { s.legacyFormat = 1; }
                else if (c == 'v') { s.verbose++; g_displayLevel++; }
                else if (c == 'q') { s.quiet++; g_displayLevel--; if (g_displayLevel < 0) g_displayLevel = 0; }
                else if (c == 'h' || c == 'H') { display_help(); return 0; }
                else if (c == 'V') {
                    fprintf(stderr, "*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***\n");
                    return 0;
                }
                else if (c == 'B') {
                    p++;
                    if (*p == 'I') { s.blockIndependence = 1; }
                    else if (*p == 'D') { s.blockIndependence = 0; }
                    else if (*p == 'X') { s.blockChecksum = 1; }
                    else if (*p >= '4' && *p <= '7') { s.blockSizeID = (LZ4F_blockSizeID_t)(*p - '0'); }
                    else { p--; }
                    break; /* B# consumes rest of arg */
                }
                else if (c == 'T') {
                    p++;
                    s.numThreads = atoi(p);
                    break;
                }
                else if (c >= '1' && c <= '9') {
                    /* Check for multi-digit level */
                    int lvl = c - '0';
                    if (*(p+1) >= '0' && *(p+1) <= '9') {
                        lvl = lvl * 10 + (*(p+1) - '0');
                        p++;
                    }
                    s.compressionLevel = lvl;
                }
                else if (c == 'b') {
                    s.mode = MODE_BENCH; mode_set = 1;
                    p++;
                    if (*p >= '0' && *p <= '9') {
                        s.benchLevel = atoi(p);
                        while (*(p+1) >= '0' && *(p+1) <= '9') p++;
                    }
                    break;
                }
                else if (c == 'e') {
                    p++;
                    if (*p >= '0' && *p <= '9') {
                        s.benchLevelEnd = atoi(p);
                        while (*(p+1) >= '0' && *(p+1) <= '9') p++;
                    }
                    break;
                }
                else if (c == 'i') {
                    p++;
                    if (*p >= '0' && *p <= '9') {
                        s.benchMinTime = atoi(p);
                        while (*(p+1) >= '0' && *(p+1) <= '9') p++;
                    }
                    break;
                }
                else if (c == '-') {
                    /* stdin */
                    if (num_inputs < 4096) input_files[num_inputs++] = "-";
                    break;
                }
                p++;
            }
            continue;
        }

        /* Non-option argument: file path */
        if (num_inputs < 4096) input_files[num_inputs++] = arg;
    }

    /* Verbose header */
    if (s.verbose >= 1) {
        fprintf(stderr, "*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***\n");
        if (s.verbose >= 2) {
            fprintf(stderr, "_POSIX_C_SOURCE defined: 200809L\n");
            fprintf(stderr, "_POSIX_VERSION defined: 200809L\n");
            fprintf(stderr, "PLATFORM_POSIX_VERSION defined: 200809L\n");
        }
        if (s.mode == MODE_COMPRESS || s.mode == MODE_BENCH) {
            int nthreads = s.numThreads > 0 ? s.numThreads : get_auto_threads();
            fprintf(stderr, "Using %d threads for compression \n", nthreads);
        }
    }

    /* Auto-detect mode from input filename */
    if (!mode_set && !is_lz4cat && !is_unlz4 && num_inputs > 0) {
        const char* first = input_files[0];
        if (strcmp(first, "-") != 0 && has_lz4_suffix(first)) {
            s.mode = MODE_DECOMPRESS;
        }
    }

    /* Handle --list mode */
    if (s.mode == MODE_LIST) {
        if (num_inputs == 0) {
            fprintf(stderr, "lz4: --list requires input files\n");
            return 1;
        }
        print_list_header();
        int result = 0;
        for (int i = 0; i < num_inputs; i++) {
            result |= do_list(input_files[i]);
        }
        return result;
    }

    /* Handle benchmark mode */
    if (s.mode == MODE_BENCH) {
        if (num_inputs == 0) {
            fprintf(stderr, "No files for benchmark\n");
            return 1;
        }
        int level_start = s.benchLevel > 0 ? s.benchLevel : 1;
        int level_end = s.benchLevelEnd >= level_start ? s.benchLevelEnd : level_start;
        int min_time = s.benchMinTime > 0 ? s.benchMinTime : 3;

        if (level_end > level_start) {
            fprintf(stderr, "Benchmarking levels from %d to %d\n\n", level_start, level_end);
        }

        fprintf(stderr, "\r%79s\r", "");
        int result = 0;
        for (int lvl = level_start; lvl <= level_end; lvl++) {
            for (int fi = 0; fi < num_inputs; fi++) {
                if (lvl > level_start || fi > 0)
                    fprintf(stderr, "\r%79s\r", "");
                result |= do_benchmark(input_files[fi], lvl, min_time);
            }
            printf("\r %d#\n", lvl);
            fflush(stdout);
        }
        return result;
    }

    /* No inputs: use stdin/stdout */
    if (num_inputs == 0) {
        /* stdin -> stdout */
        if (s.mode == MODE_DECOMPRESS) {
            return do_decompress(NULL, NULL, &s, 1, 1, 0, 0);
        } else if (s.mode == MODE_COMPRESS) {
            return do_compress(NULL, NULL, &s, 1, 1);
        }
        return 0;
    }

    /* Handle multiple files mode */
    if (s.multipleFiles || s.recursive || num_inputs > 2 ||
        (num_inputs == 1 && !output_file)) {
        /* Multiple files mode: each file gets its own output name */
        if (num_inputs == 1 && !s.multipleFiles && !s.recursive) {
            /* Single file with no output: use stdin/stdout or auto-name */
            const char* in = input_files[0];
            if (strcmp(in, "-") == 0) {
                /* stdin */
                if (s.mode == MODE_DECOMPRESS)
                    return do_decompress(NULL, NULL, &s, 1, 1, 0, 0);
                else
                    return do_compress(NULL, NULL, &s, 1, 1);
            }
            if (s.recursive && is_directory(in)) {
                return process_dir_recursive(in, &s);
            }
            return process_single_file(in, &s);
        }

        int result = 0;
        for (int i = 0; i < num_inputs; i++) {
            const char* in = input_files[i];
            if (s.recursive && is_directory(in)) {
                result |= process_dir_recursive(in, &s);
                continue;
            }
            if (strcmp(in, "-") == 0) {
                /* stdin in multi-file mode */
                if (s.mode == MODE_DECOMPRESS)
                    result |= do_decompress(NULL, NULL, &s, 1, 1, 0, 0);
                else
                    result |= do_compress(NULL, NULL, &s, 1, 1);
                continue;
            }
            result |= process_single_file(in, &s);
        }
        return result;
    }

    /* Two files: input and output */
    if (num_inputs == 2) {
        const char* in = input_files[0];
        const char* out = input_files[1];
        int is_stdin = (strcmp(in, "-") == 0 || strcmp(in, "stdin") == 0);
        int is_stdout = (strcmp(out, "-") == 0 || strcmp(out, "stdout") == 0) || s.toStdout;

        if (s.mode == MODE_DECOMPRESS || (s.mode == MODE_TEST)) {
            int auto_out = 0;
            int result;
            if (s.mode == MODE_TEST)
                result = do_decompress(in, out, &s, is_stdin, is_stdout, 1, 0);
            else
                result = do_decompress(in, out, &s, is_stdin, is_stdout, 0, auto_out);
            if (result == 0 && s.removeSource && !is_stdin) remove(in);
            return result;
        } else {
            int result = do_compress(in, out, &s, is_stdin, is_stdout);
            if (result == 0 && s.removeSource && !is_stdin) remove(in);
            return result;
        }
    }

    /* Single input, no explicit output */
    {
