/* ========== Utilities ========== */
static const char* basename_str(const char* path) {
    const char* b = strrchr(path, '/');
    return b ? b+1 : path;
}
static int file_exists(const char* path) { struct stat st; return stat(path,&st)==0; }
static long long file_size(const char* path) { struct stat st; if(stat(path,&st)!=0)return -1; return (long long)st.st_size; }
static int is_directory(const char* path) { struct stat st; if(stat(path,&st)!=0)return 0; return S_ISDIR(st.st_mode); }
static int has_lz4_suffix(const char* p) { size_t l=strlen(p); return l>4&&strcmp(p+l-4,".lz4")==0; }
static void strip_lz4_suffix(const char* p, char* out, size_t ol) {
    size_t l=strlen(p);
    if(l>4&&strcmp(p+l-4,".lz4")==0) snprintf(out,ol,"%.*s",(int)(l-4),p);
    else snprintf(out,ol,"%s",p);
}
static void* load_dict(const char* f, size_t* sz) {
    FILE* fp=fopen(f,"rb"); if(!fp){fprintf(stderr,"Can't open dict: %s\n",f);return NULL;}
    fseek(fp,0,SEEK_END); long s=ftell(fp); fseek(fp,0,SEEK_SET);
    void* d=malloc(s); if(d)(void)fread(d,1,s,fp); fclose(fp); *sz=s; return d;
}
static int ask_overwrite(const char* path) {
    DISPLAYLEVEL(1,"%s already exists; do you want to overwrite (y/N) ? ",path);
    fflush(stderr);
    int c=getchar();
    if(c!='y'&&c!='Y'){DISPLAYLEVEL(1,"    not overwritten  \n");return 0;}
    return 1;
}
static void format_size_str(char* buf, size_t bl, unsigned long long sz) {
    if(sz<1024ULL) snprintf(buf,bl,"%.2f",(double)sz);
    else if(sz<1024ULL*1024) snprintf(buf,bl,"%.2fK",(double)sz/1024.0);
    else if(sz<1024ULL*1024*1024) snprintf(buf,bl,"%.2fM",(double)sz/(1024.0*1024));
    else snprintf(buf,bl,"%.2fG",(double)sz/(1024.0*1024*1024));
}
static int get_auto_threads(void) {
    long n=sysconf(_SC_NPROCESSORS_ONLN);
    if(n<=0)return 1;
    int t=(int)(n-n/8-1);
    return t>0?t:1;
}

/* Calculate adjusted blockSizeID: min(requested, smallest_fitting_for_data_size) */
static LZ4F_blockSizeID_t adjust_blockSizeID(LZ4F_blockSizeID_t requested, long long data_size) {
    if (data_size <= 0) return requested;
    /* Find smallest blockSizeID that fits all data in one block */
    for (int bid = 4; bid <= 7; bid++) {
        if ((long long)BLOCKSIZES[bid] >= data_size) {
            int adjusted = bid < (int)requested ? (int)bid : (int)requested;
            return (LZ4F_blockSizeID_t)adjusted;
        }
    }
    return requested; /* data too large for any single block */
}

/* Read all data from FILE* into dynamically allocated buffer */
static char* read_all(FILE* f, size_t* out_size) {
    size_t cap = 4096, sz = 0;
    char* buf = malloc(cap);
    if (!buf) return NULL;
    size_t nr;
    while ((nr = fread(buf + sz, 1, cap - sz, f)) > 0) {
        sz += nr;
        if (sz == cap) {
            cap *= 2;
            char* newbuf = realloc(buf, cap);
            if (!newbuf) { free(buf); return NULL; }
            buf = newbuf;
        }
    }
    *out_size = sz;
    return buf;
}

