/* ========== Compression ========== */
static int do_compress(const char* in_path, const char* out_path,
                       const Settings* s, int is_stdin, int is_stdout) {
    FILE* fin = NULL, *fout = NULL;
    int result = 0;
    void* dict_data = NULL; size_t dict_size = 0;
    LZ4F_CDict* cdict = NULL;
    char* allbuf = NULL;

    if (is_stdin) fin = stdin;
    else {
        fin = fopen(in_path, "rb");
        if (!fin) { DISPLAYLEVEL(1, "%s: %s \n", in_path, strerror(errno)); return 1; }
    }

    if (is_stdout) fout = stdout;
    else {
        if (!s->forceOverwrite && file_exists(out_path)) {
            if (!ask_overwrite(out_path)) { if (!is_stdin) fclose(fin); return 1; }
        }
        fout = fopen(out_path, "wb");
        if (!fout) { DISPLAYLEVEL(1, "%s: %s \n", out_path, strerror(errno)); if(!is_stdin)fclose(fin); return 1; }
    }

    if (s->dictFile) {
        dict_data = load_dict(s->dictFile, &dict_size);
        if (!dict_data) { result=1; goto cleanup; }
        if (!s->legacyFormat) cdict = LZ4F_createCDict(dict_data, dict_size);
    }

    /* Determine input size and potentially adjusted blockSizeID */
    long long input_size_known = -1;
    if (!is_stdin) input_size_known = file_size(in_path);

    /* Calculate actual blockSizeID to use */
    LZ4F_blockSizeID_t actual_bsid = s->blockSizeID;
    if (!is_stdin && input_size_known >= 0) {
        actual_bsid = adjust_blockSizeID(s->blockSizeID, input_size_known);
    }

    /* Report block size if explicitly set */
    if (s->blockSizeExplicit && g_displayLevel >= 2) {
        DISPLAYLEVEL(2, "using blocks of size %zu KB \n", BLOCKSIZES[actual_bsid] >> 10);
    }

    if (s->legacyFormat) {
        /* Legacy format: need to read all data first for stdin */
        size_t allsz = 0;
        if (is_stdin) {
            allbuf = read_all(fin, &allsz);
            if (!allbuf) { result=1; goto cleanup; }
        }

        /* Write magic */
        uint8_t magic[4] = { LZ4_LEGACY_MAGIC&0xff, (LZ4_LEGACY_MAGIC>>8)&0xff,
                              (LZ4_LEGACY_MAGIC>>16)&0xff, (LZ4_LEGACY_MAGIC>>24)&0xff };
        fwrite(magic, 4, 1, fout);

        size_t bufsize = LEGACY_BLOCKSIZE;
        char* inbuf = malloc(bufsize);
        int bound = LZ4_compressBound((int)bufsize);
        char* outbuf = malloc(bound + 4);
        if (!inbuf||!outbuf) { free(inbuf);free(outbuf);result=1;goto cleanup; }

        unsigned long long total_in=0, total_out=4;
        size_t nr;
        const char* src_ptr = allbuf;
        size_t src_rem = allsz;

        for (;;) {
            if (is_stdin) {
                nr = src_rem >= bufsize ? bufsize : src_rem;
                if (nr == 0) break;
                memcpy(inbuf, src_ptr, nr);
                src_ptr += nr; src_rem -= nr;
            } else {
                nr = fread(inbuf, 1, bufsize, fin);
                if (nr == 0) break;
            }
            int csize = LZ4_compress_default(inbuf, outbuf+4, (int)nr, bound);
            if (csize<=0) { DISPLAYLEVEL(1,"compress err\n");free(inbuf);free(outbuf);result=1;goto cleanup; }
            outbuf[0]=csize&0xff; outbuf[1]=(csize>>8)&0xff; outbuf[2]=(csize>>16)&0xff; outbuf[3]=(csize>>24)&0xff;
            fwrite(outbuf, 1, 4+csize, fout);
            total_in+=nr; total_out+=4+csize;
        }
        free(inbuf); free(outbuf);

        if (g_displayLevel >= 2) {
            double ratio = total_in>0 ? (double)total_out/total_in*100.0 : 0.0;
            unsigned long long mib = total_in>>20;
            if (total_in==0) DISPLAYLEVEL(2,"\rRead : %llu MiB   ==> inf%%   ",mib);
            else DISPLAYLEVEL(2,"\rRead : %llu MiB   ==> %.2f%%   ",mib,ratio);
            DISPLAYLEVEL(2,"\r%79s\r","");
            DISPLAYLEVEL(2,"Compressed %llu bytes into %llu bytes ==> %.2f%% \n",
                          total_in, total_out,
                          total_in>0?(double)total_out/total_in*100.0:0.0);
        }
    } else {
        /* Frame format: for stdin, read all first to determine blockSizeID */
        size_t allsz = 0;
        if (is_stdin) {
            allbuf = read_all(fin, &allsz);
            if (!allbuf) { result=1; goto cleanup; }
            actual_bsid = adjust_blockSizeID(s->blockSizeID, (long long)allsz);
        }

        LZ4F_preferences_t prefs;
        memset(&prefs, 0, sizeof(prefs));
        prefs.frameInfo.blockSizeID = actual_bsid;
        prefs.frameInfo.blockMode = s->blockIndependence ? LZ4F_blockIndependent : LZ4F_blockLinked;
        prefs.frameInfo.contentChecksumFlag = s->contentChecksum ? LZ4F_contentChecksumEnabled : LZ4F_noContentChecksum;
        prefs.frameInfo.blockChecksumFlag = s->blockChecksum ? LZ4F_blockChecksumEnabled : LZ4F_noBlockChecksum;
        prefs.compressionLevel = s->compressionLevel;
        prefs.favorDecSpeed = s->favorDecSpeed;
        if (s->contentSize) {
            if (is_stdin) prefs.frameInfo.contentSize = (unsigned long long)allsz;
            else if (input_size_known > 0) prefs.frameInfo.contentSize = (unsigned long long)input_size_known;
        }
        if (s->acceleration > 0) prefs.compressionLevel = -(s->acceleration);

        LZ4F_cctx* cctx = NULL;
        LZ4F_errorCode_t err = LZ4F_createCompressionContext(&cctx, LZ4F_VERSION);
        if (LZ4F_isError(err)) { DISPLAYLEVEL(1,"ctx err:%s\n",LZ4F_getErrorName(err));result=1;goto cleanup; }

        size_t bufsize = BLOCKSIZES[actual_bsid];
        size_t dstCap = LZ4F_compressBound(bufsize, &prefs) + 512;
        char* inbuf = malloc(bufsize);
        char* outbuf = malloc(dstCap);
        if (!inbuf||!outbuf) { free(inbuf);free(outbuf);LZ4F_freeCompressionContext(cctx);result=1;goto cleanup; }

        size_t hdr;
        if (cdict) hdr = LZ4F_compressBegin_usingCDict(cctx, outbuf, dstCap, cdict, &prefs);
        else hdr = LZ4F_compressBegin(cctx, outbuf, dstCap, &prefs);
        if (LZ4F_isError(hdr)) { DISPLAYLEVEL(1,"begin err:%s\n",LZ4F_getErrorName(hdr));free(inbuf);free(outbuf);LZ4F_freeCompressionContext(cctx);result=1;goto cleanup; }
        if (hdr>0) fwrite(outbuf,1,hdr,fout);

        unsigned long long total_in=0, total_out=hdr;
        const char* src_ptr = allbuf;
        size_t src_rem = allsz;
        size_t nr;
        for (;;) {
            if (is_stdin) {
                nr = src_rem >= bufsize ? bufsize : src_rem;
                if (nr==0) break;
                memcpy(inbuf, src_ptr, nr);
                src_ptr+=nr; src_rem-=nr;
            } else {
                nr = fread(inbuf, 1, bufsize, fin);
                if (nr==0) break;
            }
            size_t w = LZ4F_compressUpdate(cctx, outbuf, dstCap, inbuf, nr, NULL);
            if (LZ4F_isError(w)) { DISPLAYLEVEL(1,"update err:%s\n",LZ4F_getErrorName(w));free(inbuf);free(outbuf);LZ4F_freeCompressionContext(cctx);result=1;goto cleanup; }
            if (w>0) fwrite(outbuf,1,w,fout);
            total_in+=nr; total_out+=w;
        }
        size_t ew = LZ4F_compressEnd(cctx, outbuf, dstCap, NULL);
        if (LZ4F_isError(ew)) { DISPLAYLEVEL(1,"end err:%s\n",LZ4F_getErrorName(ew));free(inbuf);free(outbuf);LZ4F_freeCompressionContext(cctx);result=1;goto cleanup; }
        if (ew>0) fwrite(outbuf,1,ew,fout);
        total_out+=ew;

        free(inbuf); free(outbuf);
        LZ4F_freeCompressionContext(cctx);

        if (g_displayLevel >= 2) {
            double ratio = total_in>0 ? (double)total_out/total_in*100.0 : 0.0;
            unsigned long long mib = total_in>>20;
            if (total_in==0) DISPLAYLEVEL(2,"\rRead : %llu MiB   ==> inf%%   ",mib);
            else DISPLAYLEVEL(2,"\rRead : %llu MiB   ==> %.2f%%   ",mib,ratio);
            DISPLAYLEVEL(2,"\r%79s\r","");
            DISPLAYLEVEL(2,"Compressed %llu bytes into %llu bytes ==> %.2f%%\n",
                          total_in, total_out, ratio);
        }
    }

cleanup:
    if (fin&&!is_stdin) fclose(fin);
    if (fout&&!is_stdout) fclose(fout);
    if (cdict) LZ4F_freeCDict(cdict);
    free(dict_data);
    free(allbuf);
    return result;
}

