    if (!has_ratio) printf("%10llu%15s%6s%12s%14s%9s   %s\n",frames,type,block,cs,us,"-",fname);
    else printf("%10llu%15s%6s%12s%14s%9.2f%%  %s\n",frames,type,block,cs,us,ratio,fname);
}
static int do_list(const char* path) {
    FILE* f=fopen(path,"rb"); if(!f){fprintf(stderr,"%s: %s\n",path,strerror(errno));return 1;}
    long long fsize=file_size(path);
    unsigned char buf[512];
    size_t nr=fread(buf,1,sizeof(buf),f); fclose(f);
    if (nr<4) return 1;
    uint32_t magic=(uint32_t)buf[0]|((uint32_t)buf[1]<<8)|((uint32_t)buf[2]<<16)|((uint32_t)buf[3]<<24);
    unsigned long long frames=1;
    unsigned long long cbytes=fsize>0?(unsigned long long)fsize:0;
    unsigned long long ubytes=0;
    double ratio=0.0; int has_ratio=0;
    const char* type="LZ4Frame";
    char block[8]="-";
    if (magic==LZ4_LEGACY_MAGIC) { type="LegacyFrame"; }
    else if (magic==LZ4_MAGIC) {
        LZ4F_dctx* dctx=NULL;
        LZ4F_createDecompressionContext(&dctx,LZ4F_VERSION);
        LZ4F_frameInfo_t fi; size_t consumed=nr;
        size_t ret=LZ4F_getFrameInfo(dctx,&fi,buf,&consumed);
        LZ4F_freeDecompressionContext(dctx);
        if (!LZ4F_isError(ret)) {
            char bm=(fi.blockMode==LZ4F_blockIndependent)?'I':'D';
            int bid=fi.blockSizeID;
            if (bid>=4&&bid<=7) { block[0]='B';block[1]='0'+bid;block[2]=bm;block[3]=0; }
            else snprintf(block,sizeof(block),"B?%c",bm);
            if (fi.contentSize>0) { ubytes=fi.contentSize; has_ratio=1; ratio=cbytes>0?(double)cbytes/ubytes*100.0:0.0; }
        }
    }
    const char* bname=basename_str(path);
    char fname_buf[512];
    if (has_ratio) snprintf(fname_buf,sizeof(fname_buf),"%s ",bname);
    else snprintf(fname_buf,sizeof(fname_buf),"%s",bname);
    print_list_row(frames,type,block,cbytes,ubytes,ratio,has_ratio,fname_buf);
    return 0;
}

/* ========== Benchmark ========== */
static double get_time_d(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts);
    return ts.tv_sec+ts.tv_nsec*1e-9;
}
static int do_benchmark(const char* path, int level, int min_time_sec) {
    FILE* f=fopen(path,"rb"); if(!f)return 1;
    long long fsize=file_size(path); if(fsize<=0){fclose(f);return 1;}
    char* src=malloc(fsize); if(!src){fclose(f);return 1;}
    if (fread(src,1,fsize,f)!=(size_t)fsize) { fclose(f);free(src);return 1; }
    fclose(f);
    int bound=LZ4_compressBound((int)fsize)+64;
    char* dst=malloc(bound);
    char* dec=malloc(fsize+64);
    if (!dst||!dec) { free(src);free(dst);free(dec);return 1; }
    const char* bname=basename_str(path);
    int csize=0;
    double best_ct=1e10, best_dt=1e10;

    /* Compression pass 1 */
    fprintf(stderr,"\r |-%-18.18s:%10lld ->",bname,(long long)fsize); fflush(stderr);
    double start=get_time_d();
    do {
        double t0=get_time_d();
        if (level>=10) csize=LZ4_compress_HC(src,dst,(int)fsize,bound,level);
        else csize=LZ4_compress_default(src,dst,(int)fsize,bound);
        double dt=get_time_d()-t0;
        if (dt<best_ct) best_ct=dt;
    } while (get_time_d()-start<(double)min_time_sec);
    double cspeed=fsize/(1024.0*1024.0)/best_ct;
    double cratio=csize>0?(double)csize/fsize:0.0;
    printf("\r /-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s\r",bname,(long long)fsize,csize,cratio,cspeed); fflush(stdout);

    /* Decompression pass 1 */
    fprintf(stderr,"\r =-%-18.18s:%10lld ->",bname,(long long)fsize); fflush(stderr);
    start=get_time_d();
    do {
        double t0=get_time_d();
        LZ4_decompress_safe(dst,dec,csize,(int)fsize);
        double dt=get_time_d()-t0;
        if (dt<best_dt) best_dt=dt;
    } while (get_time_d()-start<(double)min_time_sec);
    double dspeed=fsize/(1024.0*1024.0)/best_dt;
    printf("\r =-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s, %5.1f MB/s\r",bname,(long long)fsize,csize,cratio,cspeed,dspeed); fflush(stdout);

    /* Compression pass 2 */
    best_ct=1e10; start=get_time_d();
    do {
        double t0=get_time_d();
        if (level>=10) csize=LZ4_compress_HC(src,dst,(int)fsize,bound,level);
        else csize=LZ4_compress_default(src,dst,(int)fsize,bound);
        double dt=get_time_d()-t0;
        if (dt<best_ct) best_ct=dt;
    } while (get_time_d()-start<(double)min_time_sec);
    cspeed=fsize/(1024.0*1024.0)/best_ct;
    cratio=csize>0?(double)csize/fsize:0.0;
    printf("\r \\-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s\r",bname,(long long)fsize,csize,cratio,cspeed); fflush(stdout);

    /* Decompression pass 2 */
    best_dt=1e10; start=get_time_d();
    do {
        double t0=get_time_d();
        LZ4_decompress_safe(dst,dec,csize,(int)fsize);
        double dt=get_time_d()-t0;
        if (dt<best_dt) best_dt=dt;
    } while (get_time_d()-start<(double)min_time_sec);
    dspeed=fsize/(1024.0*1024.0)/best_dt;
    printf("\r |-%-18.18s:%10lld ->%10d (%.3f),%6.1f MB/s, %5.1f MB/s\r",bname,(long long)fsize,csize,cratio,cspeed,dspeed); fflush(stdout);

    free(src); free(dst); free(dec);
    return 0;
}

