/* ========== Recursive directory & single file ========== */
static int process_single_file(const char* in_path, const Settings* s);
static int process_dir(const char* dir_path, const Settings* s) {
    DIR* d=opendir(dir_path); if(!d){DISPLAYLEVEL(1,"%s: %s\n",dir_path,strerror(errno));return 1;}
    struct dirent* ent;
    int result=0;
    while ((ent=readdir(d))!=NULL) {
        if (strcmp(ent->d_name,".")==0||strcmp(ent->d_name,"..")==0) continue;
        char child[4096]; snprintf(child,sizeof(child),"%s/%s",dir_path,ent->d_name);
        if (is_directory(child)) result|=process_dir(child,s);
        else result|=process_single_file(child,s);
    }
    closedir(d); return result;
}

static int process_single_file(const char* in_path, const Settings* s) {
    if (s->mode==MODE_LIST) return do_list(in_path);

    int result=0;
    if (s->mode==MODE_DECOMPRESS||s->mode==MODE_TEST) {
        if (s->mode==MODE_TEST) {
            result=do_decompress(in_path,NULL,s,0,0,1,0);
        } else if (s->toStdout) {
            result=do_decompress(in_path,NULL,s,0,1,0,0);
        } else {
            char out[4096];
            int auto_out=0;
            if (has_lz4_suffix(in_path)) { strip_lz4_suffix(in_path,out,sizeof(out)); auto_out=1; }
            else { snprintf(out,sizeof(out),"%s",in_path); DISPLAYLEVEL(1,"%s has unknown suffix\n",in_path); return 1; }
            result=do_decompress(in_path,out,s,0,0,0,auto_out);
        }
    } else {
        char out[4096]; snprintf(out,sizeof(out),"%s.lz4",in_path);
        if (s->toStdout) result=do_compress(in_path,NULL,s,0,1);
        else result=do_compress(in_path,out,s,0,0);
    }
    if (result==0&&s->removeSource) remove(in_path);
    return result;
}

/* ========== Main ========== */
int main(int argc, char** argv) {
    Settings s;
    memset(&s,0,sizeof(s));
    s.mode=MODE_COMPRESS;
    s.blockSizeID=LZ4F_max64KB;
    s.blockIndependence=1;
    s.contentChecksum=1;
    s.benchLevel=1;
    s.benchMinTime=3;

    const char* prog=basename_str(argv[0]);
    g_progname=prog;
    int is_lz4cat=(strcmp(prog,"lz4cat")==0);
    int is_unlz4=(strcmp(prog,"unlz4")==0);

    if (is_lz4cat) { s.mode=MODE_DECOMPRESS; s.toStdout=1; s.multipleFiles=1; s.forceOverwrite=1; }
    else if (is_unlz4) { s.mode=MODE_DECOMPRESS; }

    const char* inputs[4096];
    int num_inputs=0;
    int mode_set=0;

    for (int i=1; i<argc; i++) {
        const char* arg=argv[i];

        if (strcmp(arg,"--compress")==0||strcmp(arg,"-z")==0) { s.mode=MODE_COMPRESS; mode_set=1; continue; }
        if (strcmp(arg,"--decompress")==0||strcmp(arg,"--uncompress")==0) { s.mode=MODE_DECOMPRESS; mode_set=1; continue; }
        if (strcmp(arg,"--test")==0) { s.mode=MODE_TEST; mode_set=1; continue; }
        if (strcmp(arg,"--rm")==0) { s.removeSource=1; continue; }
        if (strcmp(arg,"--keep")==0) { s.removeSource=0; continue; }
        if (strcmp(arg,"--force")==0) { s.forceOverwrite=1; continue; }
        if (strcmp(arg,"--no-frame-crc")==0) { s.contentChecksum=0; continue; }
        if (strcmp(arg,"--content-size")==0) { s.contentSize=1; continue; }
        if (strcmp(arg,"--favor-decSpeed")==0) { s.favorDecSpeed=1; continue; }
        if (strcmp(arg,"--sparse")==0||strcmp(arg,"--no-sparse")==0) continue;
        if (strcmp(arg,"--best")==0) { s.compressionLevel=12; continue; }
        if (strcmp(arg,"--fast")==0) { s.acceleration=1; continue; }
        if (strncmp(arg,"--fast=",7)==0) { s.acceleration=atoi(arg+7); if(s.acceleration<=0)s.acceleration=1; continue; }
        if (strcmp(arg,"--list")==0) { s.mode=MODE_LIST; continue; }
        if (strcmp(arg,"-D")==0) { if(i+1<argc){s.dictFile=argv[++i];} continue; }

        if (arg[0]=='-'&&arg[1]!=0) {
            const char* p=arg+1;
            int consumed_arg=0;
            while (*p&&!consumed_arg) {
                char c=*p;
