/* ========== Recursive directory & single file ========== */
static int process_single_file(const char* in_path, const Settings* s);
static int process_dir(const char* dir_path, const Settings* s) {
    DIR* d=opendir(dir_path); if(!d){DISPLAYLEVEL(1,"%s: %s\n",dir_path,strerror(errno));return 1;}
    struct dirent* ent;
    int result=0;
    while ((ent=readdir(d))!=NULL) {
        if (strcmp(ent->d_name,".")==0||strcmp(ent->d_name,"..")==0) continue;
        char child[4096]; snprintf(child,sizeof(child),"%s/%s",dir_path,ent->d_name);
        if (is_directory(child)) result|=process_dir(child,s);
        else result|=process_single_file(child,s);
    }
    closedir(d); return result;
}

static int process_single_file(const char* in_path, const Settings* s) {
    if (s->mode==MODE_LIST) return do_list(in_path);

    int result=0;
    if (s->mode==MODE_DECOMPRESS||s->mode==MODE_TEST) {
