# Let me check what the LZ4 library does when I specify BD mode for a small file
cat > /tmp/test_bd.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LZ4F_VERSION 100
typedef void* LZ4F_cctx;
typedef size_t LZ4F_errorCode_t;
typedef enum {LZ4F_default=0,LZ4F_max64KB=4,LZ4F_max256KB=5,LZ4F_max1MB=6,LZ4F_max4MB=7} LZ4F_blockSizeID_t;
typedef enum {LZ4F_blockLinked=0,LZ4F_blockIndependent} LZ4F_blockMode_t;
typedef enum {LZ4F_noContentChecksum=0,LZ4F_contentChecksumEnabled} LZ4F_contentChecksum_t;
typedef enum {LZ4F_noBlockChecksum=0,LZ4F_blockChecksumEnabled} LZ4F_blockChecksum_t;
typedef enum {LZ4F_frame=0,LZ4F_skippableFrame} LZ4F_frameType_t;
typedef struct {
    LZ4F_blockSizeID_t blockSizeID;
    LZ4F_blockMode_t blockMode;
    LZ4F_contentChecksum_t contentChecksumFlag;
    LZ4F_frameType_t frameType;
    unsigned long long contentSize;
    unsigned dictID;
    LZ4F_blockChecksum_t blockChecksumFlag;
} LZ4F_frameInfo_t;
typedef struct {
    LZ4F_frameInfo_t frameInfo;
    int compressionLevel;
    unsigned autoFlush;
    unsigned favorDecSpeed;
    unsigned reserved[3];
} LZ4F_preferences_t;
extern LZ4F_errorCode_t LZ4F_createCompressionContext(LZ4F_cctx** cctxPtr, unsigned version);
extern LZ4F_errorCode_t LZ4F_freeCompressionContext(LZ4F_cctx cctx);
extern size_t LZ4F_compressBegin(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const LZ4F_preferences_t* prefsPtr);
extern size_t LZ4F_compressUpdate(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const void* srcBuffer, size_t srcSize, const void* cOptPtr);
extern size_t LZ4F_compressEnd(LZ4F_cctx cctx, void* dstBuffer, size_t dstCapacity, const void* cOptPtr);
extern size_t LZ4F_compressBound(size_t srcSize, const LZ4F_preferences_t* prefsPtr);

int main() {
    const char* test = "The quick brown fox";
    size_t len = strlen(test);

    for (int mode = 0; mode <= 1; mode++) {
        LZ4F_preferences_t prefs;
        memset(&prefs, 0, sizeof(prefs));
        prefs.frameInfo.blockSizeID = LZ4F_max64KB;
        prefs.frameInfo.blockMode = mode;
        prefs.frameInfo.contentChecksumFlag = LZ4F_contentChecksumEnabled;

        LZ4F_cctx* cctx = NULL;
        LZ4F_createCompressionContext(&cctx, LZ4F_VERSION);

        char buf[256];
        size_t n = LZ4F_compressBegin(cctx, buf, sizeof(buf), &prefs);
        n += LZ4F_compressUpdate(cctx, buf+n, sizeof(buf)-n, test, len, NULL);
        n += LZ4F_compressEnd(cctx, buf+n, sizeof(buf)-n, NULL);

        printf("Mode %d (%s): FLG=0x%02x, total=%zu bytes\n",
               mode, mode==0?"BD":"BI", (unsigned char)buf[4], n);
        LZ4F_freeCompressionContext(cctx);
    }
    return 0;
}
EOF
